  shopFaqCustomizationQ: "What happens to my customizations if I cancel?",
  shopFaqCustomizationA:
    "Your choices (font, glow, banner, chat bubbles) are kept in your account but stop being applied, so everyone sees the default look again. Resubscribe anytime to get them back instantly.",
