  shopFaqPaymentA: "Any card accepted by Stripe (Visa, Mastercard, American Express, and more).",
  shopFaqInvoiceQ: "How do I get an invoice?",
  shopFaqInvoiceA: "Every invoice is available anytime from Purchases & Billing.",
