  shopFaqCancelQ: "¿Puedo cancelar en cualquier momento?",
  shopFaqCancelA:
    "Sí. Cancela cuando quieras desde Compras y Facturación. Conservas Spark Plus hasta el final del período ya pagado.",
  shopFaqCustomizationQ: "¿Qué pasa con mis personalizaciones si cancelo?",
  shopFaqCustomizationA:
    "Tus elecciones (fuente, brillo, banner, burbujas) se guardan en tu cuenta pero dejan de aplicarse, así que todos vuelven a ver el estilo por defecto. Vuelve a suscribirte cuando quieras para recuperarlas al instante.",
  shopFaqRenewQ: "¿Se renueva automáticamente?",
  shopFaqRenewA:
    "Sí, es una suscripción mensual que se renueva automáticamente hasta que canceles, con el mismo importe cada mes.",
  shopFaqPaymentQ: "¿Qué métodos de pago se aceptan?",
  shopFaqPaymentA:
    "Cualquier tarjeta aceptada por Stripe (Visa, Mastercard, American Express y más).",
  shopFaqInvoiceQ: "¿Cómo obtengo una factura?",
  shopFaqInvoiceA: "Cada factura está disponible en cualquier momento desde Compras y Facturación.",
  shopFaqBloxQ: "¿Qué son los Blox?",
  shopFaqBloxA:
    "Los Blox son la moneda de BloxSpark. Úsalos para comprar insignias cosméticas en la Blox Store o para regalárselos a tus Sparks y a tus creadores favoritos.",
  shopFaqBloxRefundQ: "¿Puedo pedir un reembolso de Blox?",
  shopFaqBloxRefundA:
    "Una compra de Blox es definitiva en cuanto se acredita en tu saldo, conforme a nuestra política de reembolsos. Consulta las Condiciones de la tienda para todos los detalles.",
  shopFaqBloxGiftQ: "¿Puedo regalarle Blox a alguien?",
